 // Deterministic Edit-mode level builder. Never runs in a player.
 [InitializeOnLoad] public static class AlpsTownAuthoring {
  const string Folder="Assets/Snowglow/Levels/TheAlps",ScenePath="Assets/Scenes/TheAlps.unity",Log="Logs/TheAlps";
  static readonly List<Vector3[]> hillRoutes=new List<Vector3[]>();
  static Material snow,stone,roof,road,wood,glass,bronze,white,red,dark,gold;
  static int meshId,houseCount;static Transform town;
  static AlpsTownAuthoring(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Log+".request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;string action=File.ReadAllText(Log+".request").Trim();File.Delete(Log+".request");try{if(action=="review")Review();else if(action=="polish")Polish();else if(action=="finish")FinishTown();else if(action=="regress")Regression();else Build();}catch(Exception e){Directory.CreateDirectory(Log);File.WriteAllText(Log+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Require(bool b,string s){if(!b)throw new InvalidOperationException("The Alps: "+s);}
  static Material Mat(string name,string hex){var path=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name=name,enableInstancing=true};AssetDatabase.CreateAsset(m,path);}ColorUtility.TryParseHtmlString(hex,out var c);m.SetColor("_BaseColor",c.linear);m.SetFloat("_Smoothness",.08f);EditorUtility.SetDirty(m);return m;}
  static Transform Group(string name,Transform parent,Vector3 p)=>PrimitiveKit.Group(name,parent,p);
  static GameObject Box(string name,Transform parent,Vector3 p,Vector3 size,Material m,bool solid=false)=>PrimitiveKit.Cube(name,parent,p,size,m,solid);
  static void Beam(string name,Transform p,Vector3 a,Vector3 b,float r,Material m)=>PrimitiveKit.Beam(name,p,a,b,r,m);
  static void Orb(string n,Transform p,Vector3 at,Vector3 size,Material m){var v=new List<Vector3>();var ix=new List<int>();for(int i=0;i<8;i++){float a=i*Mathf.PI/4,b=(i+1)*Mathf.PI/4;Vector3 Ring(float angle,float y,float radius)=>Vector3.Scale(new Vector3(Mathf.Sin(angle)*radius,y,Mathf.Cos(angle)*radius),size);var l=Ring(a,-.25f,.42f);var r=Ring(b,-.25f,.42f);var u=Ring(a,.25f,.42f);var w=Ring(b,.25f,.42f);Tri(v,ix,Vector3.Scale(Vector3.down*.5f,size),r,l);Quad(v,ix,r,w,u,l);Tri(v,ix,w,Vector3.Scale(Vector3.up*.5f,size),u);}Display(n,p,Mesh(n,v,ix),m).transform.localPosition=at;}
  static Mesh Mesh(string name,List<Vector3> v,List<int> ix){var mesh=new Mesh{name=name,indexFormat=v.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(v);mesh.SetTriangles(ix,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=Folder+"/Geometry_"+(meshId++).ToString("D3")+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.normals=mesh.normals;old.triangles=mesh.triangles;old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
  static GameObject Display(string n,Transform p,Mesh m,Material mat,bool solid=false){var g=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(p,false);g.GetComponent<MeshFilter>().sharedMesh=m;g.GetComponent<MeshRenderer>().sharedMaterial=mat;if(solid)g.AddComponent<MeshCollider>().sharedMesh=m;return g;}
  static void Tri(List<Vector3> v,List<int> ix,Vector3 a,Vector3 b,Vector3 c){int i=v.Count;v.AddRange(new[]{a,b,c});ix.AddRange(new[]{i,i+1,i+2});}
  static void Quad(List<Vector3> v,List<int> ix,Vector3 a,Vector3 b,Vector3 c,Vector3 d){Tri(v,ix,a,b,c);Tri(v,ix,a,c,d);}
  static Mesh Gable(float w,float d,float height){var v=new List<Vector3>();var ix=new List<int>();float x=w/2,z=d/2;var a=new Vector3(-x,0,-z);var b=new Vector3(x,0,-z);var c=new Vector3(0,height,-z);var e=new Vector3(-x,0,z);var f=new Vector3(x,0,z);var g=new Vector3(0,height,z);Tri(v,ix,a,c,b);Tri(v,ix,e,f,g);Quad(v,ix,a,e,g,c);Quad(v,ix,c,g,f,b);return Mesh("Snow pitched roof",v,ix);}
  static void Roof(Transform p,float w,float d,float y,float rise){var r=Display("Slate gable",p,Gable(w,d,rise),roof);r.transform.localPosition=Vector3.up*y;var s=Display("Deep snow roof",p,Gable(w+.35f,d+.35f,rise),snow);s.transform.localPosition=Vector3.up*(y+.24f);}
  static void PrepareRoutes(){hillRoutes.Clear();hillRoutes.Add(new[]{new Vector3(0,5,113),new Vector3(0,5,150),new Vector3(-65,9,190),new Vector3(-160,16,195),new Vector3(-225,22,235),new Vector3(-225,27,295),new Vector3(-135,32,310),new Vector3(-60,37,280),new Vector3(45,42,295),new Vector3(120,44,350)});hillRoutes.Add(new[]{new Vector3(113,5,0),new Vector3(155,5,0),new Vector3(205,10,-45),new Vector3(265,16,-85),new Vector3(300,22,-150),new Vector3(260,28,-220),new Vector3(180,34,-265),new Vector3(110,34,-260),new Vector3(40,28,-220),new Vector3(-30,21,-195),new Vector3(-90,13,-175),new Vector3(-65,5,-113)});}
  static float RawHeight(float x,float z){float r=Mathf.Max(Mathf.Abs(x),Mathf.Abs(z));float edge=Mathf.SmoothStep(0,1,Mathf.InverseLerp(140,480,r));float h=5+edge*(24+55*Mathf.PerlinNoise(x*.006f+21,z*.006f+9));foreach(var route in hillRoutes)for(int i=1;i<route.Length;i++){var a=new Vector2(route[i-1].x,route[i-1].z);var b=new Vector2(route[i].x,route[i].z);float t=Mathf.Clamp01(Vector2.Dot(new Vector2(x,z)-a,b-a)/(b-a).sqrMagnitude);float distance=Vector2.Distance(new Vector2(x,z),Vector2.Lerp(a,b,t));if(distance<26)h=Mathf.Lerp(Mathf.Lerp(route[i-1].y,route[i].y,t),h,Mathf.SmoothStep(0,1,Mathf.InverseLerp(9,26,distance)));}return h;}
  static readonly Vector2[] ChaletSites={new Vector2(-165,226),new Vector2(-194,278),new Vector2(-118,337),new Vector2(-45,310),new Vector2(69,325),new Vector2(235,-112),new Vector2(279,-190),new Vector2(168,-295),new Vector2(66,-264)};
  static Vector3 RoadPoint(Vector2 site){Vector3 closest=Vector3.zero;float best=float.MaxValue;foreach(var route in hillRoutes.Take(2))for(int i=1;i<route.Length;i++){var a=new Vector2(route[i-1].x,route[i-1].z);var b=new Vector2(route[i].x,route[i].z);float t=Mathf.Clamp01(Vector2.Dot(site-a,b-a)/(b-a).sqrMagnitude);float d=(site-Vector2.Lerp(a,b,t)).sqrMagnitude;if(d<best){best=d;closest=Vector3.Lerp(route[i-1],route[i],t);}}return closest;}
  static float Height(float x,float z){float h=RawHeight(x,z);foreach(var site in ChaletSites){var near=RoadPoint(site);float d=Vector2.Distance(site,new Vector2(x,z));if(d<23)h=Mathf.Lerp(near.y,h,Mathf.SmoothStep(0,1,Mathf.InverseLerp(10,23,d)));var a=new Vector2(near.x,near.z);var b=site;float t=Mathf.Clamp01(Vector2.Dot(new Vector2(x,z)-a,b-a)/(b-a).sqrMagnitude);float lane=Vector2.Distance(new Vector2(x,z),Vector2.Lerp(a,b,t));if(lane<8)h=Mathf.Lerp(near.y,h,Mathf.SmoothStep(0,1,Mathf.InverseLerp(4,8,lane)));}return h;}
  static void Road(string name,Vector3[] points,float width,bool lines=true){var v=new List<Vector3>();var ix=new List<int>();var samples=new List<Vector3>{points[0]};void LineTo(Vector3 end){var begin=samples[samples.Count-1];int count=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(begin,end)/.65f));for(int i=1;i<=count;i++)samples.Add(Vector3.Lerp(begin,end,(float)i/count));}for(int j=1;j<points.Length-1;j++){var incoming=points[j]-points[j-1];var outgoing=points[j+1]-points[j];float cut=Mathf.Min(14,Mathf.Min(incoming.magnitude,outgoing.magnitude)*.25f);var a=points[j]-incoming.normalized*cut;var b=points[j]+outgoing.normalized*cut;LineTo(a);for(int i=1;i<=40;i++){float t=i/40f;samples.Add((1-t)*(1-t)*a+2*(1-t)*t*points[j]+t*t*b);}}LineTo(points[points.Length-1]);var terrain=town.GetComponentInChildren<Terrain>();Vector3 Project(Vector3 p){p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.14f;return p;}for(int i=0;i<samples.Count-1;i++){Vector3 Right(int n){var dir=n==0?samples[1]-samples[0]:n==samples.Count-1?samples[n]-samples[n-1]:samples[n+1]-samples[n-1];dir.y=0;return Vector3.Cross(Vector3.up,dir.normalized)*width*.5f;}var a=samples[i];var b=samples[i+1];var ra=Right(i);var rb=Right(i+1);var l0=Project(a-ra);var c0=Project(a);var r0=Project(a+ra);var l1=Project(b-rb);var c1=Project(b);var r1=Project(b+rb);for(int column=0;column<10;column++){float t0=column/10f,t1=(column+1)/10f;Quad(v,ix,Project(a+ra*(2*t0-1)),Project(b+rb*(2*t0-1)),Project(b+rb*(2*t1-1)),Project(a+ra*(2*t1-1)));}if(lines&&i%5==0&&i+1<samples.Count-1){var at=(c0+c1)*.5f+Vector3.up*.02f;var dash=Box("Centre dash",town,at,new Vector3(.12f,.025f,1.7f),gold);dash.transform.rotation=Quaternion.LookRotation(c1-c0);}}Display(name,town,Mesh(name,v,ix),road,true);}
  static void Label(string name,Transform p,Vector3 at,string text,float size,Color color){var g=new GameObject(name);g.transform.SetParent(p,false);g.transform.localPosition=at;var t=g.AddComponent<TextMesh>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=text;t.fontSize=48;t.characterSize=size;t.anchor=TextAnchor.MiddleCenter;t.color=color;}
  static void House(Vector3 at,float angle,int variant,bool hillside=false){houseCount++;float w=10+variant%3*2,d=10+variant%2*2,h=hillside?6:9+variant%3*2;var p=Group((hillside?"Hillside chalet ":"Old-town building ")+houseCount,town,at);p.localRotation=Quaternion.Euler(0,angle,0);var wall=Mat("Facade_"+variant%5,new[]{"#E5D3B8","#E7B999","#D1D9CD","#D0BD9F","#DACBC5"}[variant%5]);Box("Stone footing",p,new Vector3(0,.3f,0),new Vector3(w+.6f,.6f,d+.6f),stone,true);Box("Plaster walls",p,new Vector3(0,h/2+.5f,0),new Vector3(w,h,d),wall,true);Roof(p,w+1.5f,d+1.6f,h+.6f,3.6f);Box("Timber balcony belt",p,new Vector3(0,h*.57f,0),new Vector3(w+.12f,.3f,d+.12f),wood);for(int side=0;side<4;side++){var f=Group("Facade "+side,p,Vector3.zero);f.localRotation=Quaternion.Euler(0,side*90,0);float face=side%2==0?w:d,depth=side%2==0?d:w;for(int floor=0;floor<(hillside?2:3);floor++)for(int bay=0;bay<3;bay++){float x=(bay-1)*face*.29f,y=2+floor*(h-2)/3;Box("Window recess",f,new Vector3(x,y,-depth/2-.055f),new Vector3(1.45f,1.75f,.16f),wood);Box("Warm glass",f,new Vector3(x,y,-depth/2-.15f),new Vector3(1.15f,1.45f,.045f),glass);foreach(float s in new[]{-1f,1})Box("Painted shutter",f,new Vector3(x+s*1.04f,y,-depth/2-.12f),new Vector3(.55f,1.8f,.12f),variant%2==0?dark:red);Box("Snow sill",f,new Vector3(x,y-.91f,-depth/2-.24f),new Vector3(1.8f,.15f,.5f),snow);}if(side==0){Box("Shop door",f,new Vector3(0,1.4f,-depth/2-.18f),new Vector3(1.65f,2.6f,.2f),wood);Box("Awning",f,new Vector3(0,3,-depth/2-.7f),new Vector3(4,.22f,1.6f),variant%2==0?red:dark);}}Box("Chimney",p,new Vector3(w*.27f,h+3,d*.24f),new Vector3(.9f,3,1),stone);Box("Chimney cap",p,new Vector3(w*.27f,h+4.55f,d*.24f),new Vector3(1.2f,.2f,1.3f),snow);if(!hillside&&variant%3==0){Box("Balcony floor",p,new Vector3(0,4.4f,-d/2-.8f),new Vector3(w*.75f,.25f,1.7f),wood);Box("Balcony railing",p,new Vector3(0,5.2f,-d/2-1.55f),new Vector3(w*.75f,.12f,.12f),wood);for(int i=0;i<9;i++)Box("Baluster",p,new Vector3((i-4)*w*.08f,4.9f,-d/2-1.55f),new Vector3(.12f,1,.12f),wood);}Combine(p);}
  // Merge decorative pieces per material; collision boxes remain independent.
  static void Combine(Transform root){var filters=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterials.Length==1).ToArray();foreach(var group in filters.GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial)){var instances=group.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(instances,true,true);mesh.RecalculateBounds();string path=Folder+"/Geometry_"+(meshId++).ToString("D3")+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.triangles=mesh.triangles;old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);Display("Combined | "+group.Key.name,root,mesh,group.Key);foreach(var f in group){UnityEngine.Object.DestroyImmediate(f.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(f);}}}
  static void Limb(Transform p,string n,Vector3 a,Vector3 b,float r){Beam(n,p,a,b,r,bronze);Orb(n+" joint",p,b,Vector3.one*r*1.15f,bronze);}
  static void Monument(){var p=Group("LANDMARK | Wilhelm Tell and son | original low-poly interpretation",town,new Vector3(18,5.15f,27));for(int i=0;i<3;i++)Box("Plinth step",p,new Vector3(0,.2f+i*.35f,0),new Vector3(11-i,.4f,9-i),stone,true);Box("Stone pedestal",p,new Vector3(0,2.1f,0),new Vector3(7,2.3f,5),stone,true);Box("Snow cornice",p,new Vector3(0,3.35f,0),new Vector3(7.8f,.28f,5.8f),snow);Label("Dedication",p,new Vector3(0,2,-2.53f),"WILHELM TELL",.22f,new Color(.18f,.23f,.23f));var figure=Group("Tell | bronze figure",p,new Vector3(-.6f,3.5f,0));Limb(figure,"Left leg",new Vector3(-.5f,.2f,.2f),new Vector3(-.65f,2.1f,0),.62f);Limb(figure,"Right leg",new Vector3(.7f,.2f,-.2f),new Vector3(.5f,2.1f,0),.62f);Orb("Tunic",figure,new Vector3(0,2.9f,0),new Vector3(2.1f,2.6f,1.2f),bronze);Orb("Head",figure,new Vector3(0,4.65f,0),new Vector3(.95f,1.2f,.9f),bronze);Orb("Cap",figure,new Vector3(0,5.2f,.08f),new Vector3(1.2f,.4f,1.2f),bronze);Orb("Beard",figure,new Vector3(0,4.3f,-.42f),new Vector3(.65f,.8f,.5f),bronze);Limb(figure,"Raised left upper arm",new Vector3(-.8f,3.6f,0),new Vector3(-1.4f,3.6f,-.1f),.5f);Limb(figure,"Raised left forearm",new Vector3(-1.4f,3.6f,-.1f),new Vector3(-1.25f,4.35f,-.15f),.4f);Limb(figure,"Arm around son",new Vector3(.8f,3.6f,0),new Vector3(1.9f,3.1f,.1f),.45f);Beam("Crossbow stock",figure,new Vector3(-2.1f,4.1f,.1f),new Vector3(.8f,3.85f,.1f),.18f,bronze);Beam("Crossbow bow",figure,new Vector3(-1.6f,4.2f,-1),new Vector3(-1.6f,4.2f,1.1f),.13f,bronze);var son=Group("Walter | son",p,new Vector3(1.7f,3.5f,0));Orb("Child coat",son,new Vector3(0,1.65f,0),new Vector3(1.2f,1.8f,.9f),bronze);Orb("Child head",son,new Vector3(0,2.9f,-.02f),new Vector3(.75f,.85f,.75f),bronze);foreach(float x in new[]{-.3f,.3f})Limb(son,"Child leg",new Vector3(x,.1f,0),new Vector3(x,1.3f,0),.35f);Limb(son,"Child arm",new Vector3(-.45f,2,0),new Vector3(-.7f,2.6f,0),.3f);for(int i=0;i<8;i++){float a=i*Mathf.PI/4;var at=new Vector3(Mathf.Sin(a)*7,.65f,Mathf.Cos(a)*6);PrimitiveKit.Part("Bollard",PrimitiveType.Cylinder,p,at,new Vector3(.35f,.65f,.35f),stone,true);}Combine(p);}
  static void Tower(){var p=Group("LANDMARK | Alpine gate and clock tower",town,new Vector3(-19,5.15f,77));Box("West stone pier",p,new Vector3(-4.75f,3,0),new Vector3(3.5f,6,8),stone,true);Box("East stone pier",p,new Vector3(4.75f,3,0),new Vector3(3.5f,6,8),stone,true);Box("Tower upper storeys",p,new Vector3(0,12,0),new Vector3(13,12,8),stone,true);Roof(p,15,10,18,5);for(int side=0;side<2;side++){var f=Group("Tower face",p,Vector3.zero);f.localRotation=Quaternion.Euler(0,side*180,0);for(int i=0;i<9;i++){float a=i*Mathf.PI/8;var b=Box("Arch voussoir",f,new Vector3(Mathf.Cos(a)*3.6f,5+Mathf.Sin(a)*1.7f,-4.2f),new Vector3(.9f,1.1f,.4f),white);b.transform.localRotation=Quaternion.Euler(0,0,a*Mathf.Rad2Deg-90);}var clock=PrimitiveKit.Part("Clock dial",PrimitiveType.Cylinder,f,new Vector3(0,13,-4.1f),new Vector3(4.5f,.08f,4.5f),white);clock.transform.localRotation=Quaternion.Euler(90,0,0);for(int i=0;i<12;i++){float a=i*Mathf.PI/6;var tick=Box("Hour mark",f,new Vector3(Mathf.Sin(a)*1.8f,13+Mathf.Cos(a)*1.8f,-4.23f),new Vector3(.13f,.4f,.05f),dark);tick.transform.localRotation=Quaternion.Euler(0,0,-i*30);}Beam("Minute hand",f,new Vector3(0,13,-4.3f),new Vector3(0,14.55f,-4.3f),.08f,dark);Beam("Hour hand",f,new Vector3(0,13,-4.3f),new Vector3(1,12.7f,-4.3f),.12f,dark);Box("Swiss shield",f,new Vector3(0,9,-4.2f),new Vector3(2,2.2f,.12f),red);Box("Cross vertical",f,new Vector3(0,9,-4.3f),new Vector3(.4f,1.5f,.05f),white);Box("Cross horizontal",f,new Vector3(0,9,-4.3f),new Vector3(1.4f,.4f,.05f),white);}Beam("Flagpole",p,new Vector3(0,22,0),new Vector3(0,27,0),.12f,gold);Box("Swiss flag",p,new Vector3(1.4f,26,0),new Vector3(2.6f,1.8f,.07f),red);Box("Flag cross",p,new Vector3(1.4f,26,-.045f),new Vector3(.3f,1.2f,.02f),white);Box("Flag cross",p,new Vector3(1.4f,26,-.05f),new Vector3(1.2f,.3f,.02f),white);Combine(p);}
  static void Peak(Vector3 at,float radius,float height,int seed){var rng=new System.Random(seed);var p=Group("Faceted ridge "+seed,town,at);var v=new List<Vector3>();var ix=new List<int>();var sv=new List<Vector3>();var si=new List<int>();const int n=13;var rings=new Vector3[3][];for(int ring=0;ring<3;ring++){rings[ring]=new Vector3[n];for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;float factor=.8f+(float)rng.NextDouble()*.35f;float r=radius*(ring==0?1:ring==1?.64f:.30f)*factor;float y=ring==0?0:height*(ring==1?.30f:.67f)*( .82f+(float)rng.NextDouble()*.36f);rings[ring][i]=new Vector3(Mathf.Sin(a)*r+ring*radius*.05f,y,Mathf.Cos(a)*r-ring*radius*.06f);}}for(int r=0;r<2;r++)for(int i=0;i<n;i++){int j=(i+1)%n;Quad(v,ix,rings[r][j],rings[r+1][j],rings[r+1][i],rings[r][i]);}var top=new Vector3(radius*.23f,height,-radius*.20f);for(int i=0;i<n;i++){int j=(i+1)%n;Tri(sv,si,rings[2][j],top,rings[2][i]);}Display("Exposed fractured rock",p,Mesh("Fractured ridge",v,ix),stone);Display("Irregular snow summit",p,Mesh("Irregular snow summit",sv,si),snow);}
  static void Facilities(){var depot=Group("Municipal alpine depot | recovery and service",town,new Vector3(-97,5.15f,-107));Box("Workshop",depot,new Vector3(0,4,0),new Vector3(29,8,12),stone,true);Roof(depot,32,15,8.2f,2.5f);foreach(float x in new[]{-9f,0,9}){Box("Roller door",depot,new Vector3(x,2.9f,6.05f),new Vector3(7.5f,5.8f,.12f),dark);for(int i=0;i<9;i++)Box("Door seam",depot,new Vector3(x,.6f+i*.6f,6.13f),new Vector3(7.4f,.04f,.035f),stone);}Label("Depot sign",depot,new Vector3(0,7,6.15f),"ALPINE WINTER WORKS",.22f,Color.white);var dump=Group("Snow disposal yard",town,new Vector3(94,5.15f,-85));Box("Yard slab",dump,new Vector3(0,-.06f,0),new Vector3(34,.12f,32),road,true);Box("Back wall",dump,new Vector3(0,1,-15),new Vector3(34,2,1),stone,true);foreach(float x in new[]{-17f,17})Box("Side retaining wall",dump,new Vector3(x,1,0),new Vector3(1,2,30),stone,true);Label("Disposal sign",dump,new Vector3(0,2.5f,-14.4f),"SNOW STORAGE",.23f,Color.white);var station=Group("Diesel service island",town,new Vector3(-112,5.15f,-82));Box("Pump",station,new Vector3(0,1.1f,0),new Vector3(1.2f,2.2f,.8f),red,true);Box("Meter",station,new Vector3(0,1.6f,-.42f),new Vector3(.8f,.5f,.08f),dark);Beam("Service hose",station,new Vector3(.7f,1.7f,0),new Vector3(1.2f,.3f,0),.1f,dark);}
