   var sun=new GameObject("Alpine morning sun").AddComponent<Light>();sun.transform.SetParent(town);sun.type=LightType.Directional;sun.intensity=1.35f;sun.color=new Color(1,.94f,.84f);sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(38,-38,0);RenderSettings.ambientLight=new Color(.68f,.77f,.87f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogStartDistance=350;RenderSettings.fogEndDistance=1400;RenderSettings.fogColor=new Color(.67f,.77f,.86f);
