  public static void Validate(Scene scene){var s=All<PrototypeSession>(scene).Single();Require(s.TownId=="alps","identity");Require(s.CameraRig.terrain.terrainData.size.x==1000&&s.CameraRig.terrain.terrainData.size.z==1000,"one kilometre");Require(AssetDatabase.GetAssetPath(s.Snow.seed).StartsWith(Folder+"/",StringComparison.Ordinal),"independent snow seed");Require(s.Fleet.Length==2&&s.Fleet.All(m=>m.GetComponent<Rigidbody>()&&m.Tool),"fleet");Require(All<Light>(scene).Count(l=>l.type==LightType.Directional)==1,"single sun");Require(All<Transform>(scene).Any(t=>t.name.StartsWith("LANDMARK | Wilhelm")),"Tell monument");Require(All<Transform>(scene).Any(t=>t.name.StartsWith("LANDMARK | Alpine gate")),"gate tower");Require(s.HUD&&s.HUD.productionMenu&&s.Audio&&s.Input,"UI and systems");for(int k=0;k<3;k++){var bounds=SnowField.ContractBounds(k);int count=0,clear=0;for(int i=0;i<s.Snow.seed.grid.depth.Length;i++)if(CareerSnowState.Inside(bounds,s.Snow.seed.grid.X(i),s.Snow.seed.grid.Z(i))){count++;if(s.Snow.seed.grid.depth[i]<.07f)clear++;}Require(count>0&&(float)clear/count<.15f,"venue "+k+" starts with real snow");}Require(All<Camera>(scene).Count(c=>c.GetComponent<AudioListener>())==1,"audio listener");}
  static void LoadPalette(){snow=Mat("Alpine snow","#EDF4F8");stone=Mat("Alpine limestone","#959C9E");roof=Mat("Slate","#404C5B");road=Mat("Asphalt","#657580");wood=Mat("Walnut","#74523B");glass=Mat("Warm windows","#FFD57E");bronze=Mat("Tell patinated bronze","#48776E");white=Mat("Ivory stone","#D7D6C9");red=Mat("Swiss red","#B74D45");dark=Mat("Shutters","#365960");gold=Mat("Road markings","#E2C271");}
  public static void Review(){BackupActive();var s=EditorSceneManager.OpenScene(ScenePath);Validate(s);RoadChecks(s);ProductionMenuChecks.ValidateAuthored(All<PrototypeHUD>(s).Single());Capture(s);EditorSceneManager.OpenScene(ScenePath);File.WriteAllText(Log+"/Validation.txt","PASS: independent 1000m town saved and reopened; terrain, fleet, UI, seed, three snowy venues, landmark, single sun/audio listener checked. Native renders captured. No Play/device acceptance in this report.");}
  public static void Polish(){BackupActive();var scene=EditorSceneManager.OpenScene(ScenePath);Directory.CreateDirectory(Log);File.Copy(ScenePath,Log+"/TheAlps-before-polish.unity",true);LoadPalette();PrepareRoutes();meshId=6000;town=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("THE ALPS |")).transform;var session=All<PrototypeSession>(scene).Single();var terrain=session.CameraRig.terrain.terrainData;var h=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++)h[z,x]=Height(x/256f*1000-500,z/256f*1000-500)/180;terrain.SetHeights(0,0,h);EditorUtility.SetDirty(terrain);
   foreach(var chalet in All<Transform>(scene).Where(t=>t.name.StartsWith("Hillside chalet"))){var at=chalet.position;at.y=Height(at.x,at.z)+.15f;chalet.position=at;}
   foreach(var site in ChaletSites){var near=RoadPoint(site);Road("Chalet access lane",new[]{near,new Vector3(site.x,near.y,site.y)},5,false);}
   Road("Gate passage",new[]{new Vector3(-19,5,65),new Vector3(-19,5,110)},6,false);
   foreach(var tree in All<Transform>(scene).Where(t=>t.name.StartsWith("Alpine spruce ")).ToArray()){var at=tree.position;if(ChaletSites.Any(site=>Vector2.Distance(new Vector2(at.x,at.z),site)<18)){UnityEngine.Object.DestroyImmediate(tree.gameObject);continue;}tree.rotation=Quaternion.Euler(0,tree.eulerAngles.y,0);AlpsBorrowedScenery.SeatTree(tree.gameObject,All<Terrain>(scene).Single());}
   var old=All<Transform>(scene).Single(t=>t.name.StartsWith("LANDMARK | Wilhelm"));UnityEngine.Object.DestroyImmediate(old.gameObject);Monument();
   foreach(var label in All<TextMesh>(scene).Where(t=>t.text==""))UnityEngine.Object.DestroyImmediate(label.gameObject);
   foreach(var peak in All<Transform>(scene).Where(t=>t.name.StartsWith("Faceted ridge ")).ToArray())UnityEngine.Object.DestroyImmediate(peak.gameObject);
   for(int i=0;i<10;i++){float a=i*Mathf.PI*2/10;float x=Mathf.Sin(a)*420,z=Mathf.Cos(a)*420;Peak(new Vector3(x,Height(x,z)-5,z),95+i%3*22,125+i%4*24,510+i);}
   AssetDatabase.SaveAssets();Require(EditorSceneManager.SaveScene(scene),"polish save");Review();
  }
  static void BackupActive(){var active=SceneManager.GetActiveScene();if(active.isDirty){Directory.CreateDirectory(Log);Require(EditorSceneManager.SaveScene(active,Log+"/Unsaved-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true),"preserve unsaved scene before opening level");}}
  static void RegisterBlocks(){var library=CatalogPreparation.Library();var assemblies=town.Cast<Transform>().Where(t=>t.name.StartsWith("Old-town building")||t.name.StartsWith("Hillside chalet")||t.name.StartsWith("LANDMARK |")).ToArray();Directory.CreateDirectory(Folder+"/Prefabs");for(int i=0;i<assemblies.Length;i++){string id="alps-assembly-"+(i+1).ToString("D2");var source=assemblies[i];var a=library.Find(id);if(!a){a=ScriptableObject.CreateInstance<CatalogAsset>();a.id=id;AssetDatabase.CreateAsset(a,"Assets/Snowglow/Catalog/Entries/"+id+".asset");library.entries.Add(a);}a.displayName=source.name;a.kind=CatalogKind.BuildingAssembly;a.status=PreparationStatus.NeedsReview;a.sourceType=AssetSource.ReferenceImage;a.creationSourcePath="Assets/Snowglow/Editor/AlpsTownAuthoring.cs";a.sourcePath="Assets/Snowglow/UI/Production/Towns/alps.jpg";a.sourceGuid=AssetDatabase.AssetPathToGUID(a.sourcePath);a.provenance="Original stylized Swiss alpine architecture / Tell monument generated in Edit mode using the existing Alps card as visual reference. No external model downloaded. Generator retained.";a.assumptions="Metres, Y-up. Authored colliders and appearance remain reviewable. Presentation is an original interpretation, not a real-town survey.";a.minimumScale=a.maximumScale=1;a.blocksSnow=true;a.tags=new[]{"the-alps","authored-town","reference-inspired"};var cp=source.GetComponent<CatalogPlacement>();if(!cp)cp=source.gameObject.AddComponent<CatalogPlacement>();cp.assetId=id;cp.placementId=id;var copy=UnityEngine.Object.Instantiate(source.gameObject);copy.transform.SetParent(null);copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);a.prefab=PrefabUtility.SaveAsPrefabAsset(copy,Folder+"/Prefabs/"+id+".prefab");UnityEngine.Object.DestroyImmediate(copy);CatalogPreparation.RecordMetrics(a);EditorUtility.SetDirty(a);}EditorUtility.SetDirty(library);}
  public static void FinishTown(){BackupActive();var scene=EditorSceneManager.OpenScene(ScenePath);File.Copy(ScenePath,Log+"/TheAlps-before-finish.unity",true);LoadPalette();PrepareRoutes();meshId=8000;for(int i=0;i<5;i++)Mat("Facade_"+i,new[]{"#E5D3B8","#E7B999","#D1D9CD","#D0BD9F","#DACBC5"}[i]);town=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("THE ALPS |")).transform;
   // Refit only the graded surfaces; retain contract snow seed and valley layout.
   foreach(var r in town.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Scenic mountain road")||f.name=="Chalet access lane").ToArray())UnityEngine.Object.DestroyImmediate(r.gameObject);
   foreach(var d in All<Transform>(scene).Where(t=>t.name=="Centre dash").ToArray())UnityEngine.Object.DestroyImmediate(d.gameObject);
   foreach(var route in hillRoutes)Road("Scenic mountain road | terrain fitted",route,9);
   foreach(var site in ChaletSites){var near=RoadPoint(site);Road("Chalet access lane",new[]{near,new Vector3(site.x,near.y,site.y)},5,false);}
   foreach(var peak in All<Transform>(scene).Where(t=>t.name.StartsWith("Faceted ridge ")).ToArray())UnityEngine.Object.DestroyImmediate(peak.gameObject);for(int i=0;i<10;i++){float a=i*Mathf.PI*2/10;float x=Mathf.Sin(a)*420,z=Mathf.Cos(a)*420;Peak(new Vector3(x,Height(x,z)-5,z),95+i%3*22,125+i%4*24,510+i);}
   var marks=Group("Combined road markings",town,Vector3.zero);foreach(var d in All<Transform>(scene).Where(t=>t.name=="Centre dash").ToArray())d.SetParent(marks,true);Combine(marks);
   int removed=0;foreach(var t in town.GetComponentsInChildren<Transform>(true).Reverse().ToArray())if(t!=town&&t.childCount==0&&t.GetComponents<Component>().Length==1){UnityEngine.Object.DestroyImmediate(t.gameObject);removed++;}
   var sun=All<Light>(scene).Single(l=>l.type==LightType.Directional);sun.intensity=.95f;RenderSettings.ambientLight=new Color(.39f,.46f,.54f);RenderSettings.fogColor=new Color(.55f,.67f,.78f);
   var groundTerrain=All<Terrain>(scene).Single();groundTerrain.terrainData.SyncHeightmap();groundTerrain.Flush();float oldError=0;string oldSurface="";
   foreach(var filter in All<MeshFilter>(scene).Where(f=>f.GetComponent<MeshCollider>()&&f.transform.parent==town)){var mesh=filter.sharedMesh;Require(AssetDatabase.GetAssetPath(mesh).StartsWith(Folder+"/",StringComparison.Ordinal),"road fitting cannot touch shared source assets");var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++){var point=filter.transform.TransformPoint(vertices[i]);float height=groundTerrain.SampleHeight(point)+groundTerrain.transform.position.y+.14f;float error=Mathf.Abs(height-point.y);if(error>oldError){oldError=error;oldSurface=filter.name+" at "+point.ToString("F3");}point.y=height;vertices[i]=filter.transform.InverseTransformPoint(point);}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);var collider=filter.GetComponent<MeshCollider>();collider.sharedMesh=null;collider.sharedMesh=mesh;}
   File.WriteAllText(Log+"/RoadRefit.txt","Normalized all saved road vertices against the saved terrain before final collision cooking. Largest old deviation "+oldError+"m: "+oldSurface);
   RegisterBlocks();All<PrototypeHUD>(scene).Single().productionMenu.RefreshTownText("alps");AssetDatabase.SaveAssets();Require(EditorSceneManager.SaveScene(scene),"final town save");
   var used=new HashSet<string>(AssetDatabase.GetDependencies(new[]{ScenePath,CatalogPreparation.LibraryPath},true));foreach(var path in Directory.GetFiles(Folder,"Geometry_*.asset").Select(p=>p.Replace('\\','/')).ToArray())if(!used.Contains(path))AssetDatabase.DeleteAsset(path);
   Review();File.WriteAllText(Log+"/Optimization.txt","Removed "+removed+" empty transform objects after decorative mesh merging. Graded roads refitted at 2m spacing, with shared cross sections and terrain-height sampling. Road markings merged; new architecture registered as NeedsReview catalogue assemblies. Shared Pinefall materials/seeds untouched.");
  }
  static void RoadChecks(Scene scene){var terrain=All<Terrain>(scene).Single();int vertices=0,faces=0;float maxBurial=0,maxRise=0;string worstBurial="",worstRise="";foreach(var filter in All<MeshFilter>(scene).Where(f=>f.GetComponent<MeshCollider>()&&f.transform.parent&&f.transform.parent.name.StartsWith("THE ALPS |"))){var mesh=filter.sharedMesh;Require(mesh&&AssetDatabase.Contains(mesh),"persisted road mesh");var points=mesh.vertices;foreach(var v in points){var p=filter.transform.TransformPoint(v);Require(!float.IsNaN(p.y)&&!float.IsInfinity(p.y),"finite road point");float ground=terrain.SampleHeight(p)+terrain.transform.position.y;if(ground-p.y>maxBurial){maxBurial=ground-p.y;worstBurial=filter.name+" at "+p.ToString("F3");}if(p.y-ground>maxRise){maxRise=p.y-ground;worstRise=filter.name+" at "+p.ToString("F3");}vertices++;}var ix=mesh.triangles;for(int i=0;i<ix.Length;i+=3){var a=points[ix[i]];var b=points[ix[i+1]];var c=points[ix[i+2]];Require(Vector3.Cross(b-a,c-a).y>0,"upward road collision winding");var centre=filter.transform.TransformPoint((a+b+c)/3);float under=terrain.SampleHeight(centre)+terrain.transform.position.y-centre.y;if(under>maxBurial){maxBurial=under;worstBurial=filter.name+" face centre "+centre.ToString("F3");}faces++;}}File.WriteAllText(Log+"/RoadClearanceDetails.txt","Burial "+maxBurial+" "+worstBurial+" / Rise "+maxRise+" "+worstRise);Require(maxBurial<.02f&&maxRise<.3f,"road surface remains above terrain: burial "+maxBurial+" "+worstBurial+" rise "+maxRise+" "+worstRise);File.WriteAllText(Log+"/RoadChecks.txt","PASS: "+vertices+" road vertices / "+faces+" collision triangles. Finite, persistent, upward winding, sampled above terrain. Max burial "+maxBurial+"m / road clearance "+maxRise+"m. These are geometry checks, not an exhaustive driving test.");}
  public static void Regression(){BackupActive();var scene=EditorSceneManager.OpenScene("Assets/Scenes/Pinefall.unity");var session=All<PrototypeSession>(scene).Single();ProductionMenuChecks.Run(session.HUD);SceneValidation.Validate(scene);MechanicsChecks.Run();RecoveryPhysicsChecks.Run();EditorSceneManager.OpenScene(ScenePath);File.WriteAllText(Log+"/Regression.txt","PASS: existing Pinefall scene, UI/session/progression, Career snow and recovery regressions. Disposable fixtures, no profile or scene writes.");}
  static void Capture(Scene scene){var hud=All<PrototypeHUD>(scene).Single();bool was=hud.gameObject.activeSelf;hud.gameObject.SetActive(false);var s=All<PrototypeSession>(scene).Single();var camera=s.CameraRig.view;var target=camera.targetTexture;var pos=camera.transform.position;var rot=camera.transform.rotation;bool ortho=camera.orthographic;float fov=camera.fieldOfView;var rt=RenderTexture.GetTemporary(1600,900,24);camera.targetTexture=rt;camera.orthographic=false;camera.fieldOfView=55;foreach(var shot in new[]{"Overview","TellSquare","Hills"}){var at=shot=="Overview"?new Vector3(245,210,-290):shot=="TellSquare"?new Vector3(47,15,-12):new Vector3(-160,90,220);var look=shot=="Overview"?new Vector3(0,12,30):shot=="TellSquare"?new Vector3(10,12,40):new Vector3(-80,20,70);camera.transform.position=at;camera.transform.LookAt(look);camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1600,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,900),0,0);texture.Apply();File.WriteAllBytes(Log+"/"+shot+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);RenderTexture.active=previous;}camera.targetTexture=target;camera.transform.SetPositionAndRotation(pos,rot);camera.orthographic=ortho;camera.fieldOfView=fov;RenderTexture.ReleaseTemporary(rt);hud.gameObject.SetActive(was);}
 }
